 auto texA=root/"Assets/a.tga",texB=root/"Assets/b.tga";image(texA,80,120,50);image(texB,170,80,30);assets.Scan(root.string(),(root/"Assets").string());AssetRecord a,basset;Check(assets.Track(texA.string(),a,error)&&assets.Track(texB.string(),basset,error),"register real terrain palette textures");
 auto painted=changed;painted.layers={{"grass",a.id,2},{"soil",basset.id,3}};Write(path,SerializeTerrain(painted));Check(CookTerrain(painted,path.string(),root.string(),assets,second,error),"publish registered two-layer terrain");auto meshBefore=Read(model),collisionBefore=Read(collider);TerrainDraft paint;paint.source=painted;TerrainBrush pb;pb.kind=TerrainBrushKind::Paint;pb.radius=3;pb.strength=.75;pb.layer=1;auto revision=paint.GeometryRevision();paint.Begin({0,2,0},pb,error);paint.End();Check(paint.GeometryRevision()==revision&&paint.source.heights==painted.heights,"paint never edits geometry revision or heights");bool weights=true;for(auto w:paint.source.weights)weights&=std::abs(w[0]+w[1]-1)<1e-6&&w[2]==0&&w[3]==0;Check(weights&&std::abs(paint.source.weights[144][1]-.75f)<1e-6,"analytic spatial paint blend normalized");TextureData blended;Check(PaintTerrainTexture(paint.source,assets,blended,error)&&blended.pixels[3]==255,"real texture blend produces opaque base color");Write(path,SerializeTerrain(paint.source));Check(CookTerrain(paint.source,path.string(),root.string(),assets,second,error)&&!second.geometryChanged&&second.appearanceChanged&&Read(model)==meshBefore&&Read(collider)==collisionBefore,"paint-only cook preserves exact mesh/collider bytes");Check(VerifyImportedModelFresh(root.string(),model.string(),error),"updated paint receipt validates export");

 // Lifetime/conflict and independent-source controls use real bytes, not mtimes.
 Check(reopen.Open(path.string(),error)&&reopen.source.weights==paint.source.weights,"saved source reopens exact paint values");b.kind=TerrainBrushKind::Raise;b.strength=.5f;reopen.Begin({0,0,0},b,error);reopen.End();Check(reopen.Save(error)&&reopen.Undo()&&reopen.Dirty(),"undo after Save is dirty and does not rewrite disk");Check(reopen.Redo()&&reopen.Save(error),"redo and source publication remain usable");auto sharedSource=reopen.source;auto independent=ForkTerrain(sharedSource);TerrainDraft independentDraft;independentDraft.source=independent;independentDraft.Begin({0,0,0},b,error);independentDraft.End();Check(sharedSource.heights!=independentDraft.source.heights&&sharedSource.heights==reopen.source.heights,"independent fork editing cannot change original source");
 auto good=Read(model);auto metaPath=texA.string()+".judasmeta",originalMeta=Read(metaPath);Write(path,SerializeTerrain(paint.source));bool changedMeta=false;Check(!CookTerrain(paint.source,path.string(),root.string(),assets,second,error,[&]{if(!changedMeta){changedMeta=true;Write(metaPath,originalMeta+"\n");}return false;})&&Read(model)==good,"changed layer registration during cook retains last good geometry");Write(metaPath,originalMeta);Check(CookTerrain(paint.source,path.string(),root.string(),assets,second,error),"restore dependency and recook succeeds");
 auto retained=Read(collider);auto receiptFile=root/paint.source.productDirectory/"terrain.receipt.json";auto receiptBefore=Read(receiptFile);bool replaced=false;Check(!CookTerrain(paint.source,path.string(),root.string(),assets,second,error,[&]{if(!replaced){replaced=true;Write(collider,retained+"changed");}return false;})&&Read(receiptFile)==receiptBefore&&Read(collider)==retained+"changed","concurrent retained collider change rejects cook and preserves external edit/old receipt");Write(collider,retained);
 auto invalidCounts=SerializeTerrain(t);auto nxAt=invalidCounts.find("\"nx\": 17");invalidCounts.replace(nxAt,8,"\"nx\": 17.5");Check(!ParseTerrain(invalidCounts,round,error),"fractional sample count rejected rather than truncated");invalidCounts=SerializeTerrain(t);nxAt=invalidCounts.find("\"nx\": 17");invalidCounts.replace(nxAt,8,"\"nx\": 4294967313");Check(!ParseTerrain(invalidCounts,round,error),"overflowing sample count rejected before unsigned narrowing/allocation");
 auto custom=CreateTerrain(17,17,16,16);custom.productDirectory="Content/Terrain/"+custom.identity;auto customPath=root/"Imports/custom.judasterrain";Write(customPath,SerializeTerrain(custom));fs::create_directories(root/"Content");AssetDatabase customAssets;customAssets.Scan(root.string(),(root/"Content").string());Check(CookTerrain(custom,customPath.string(),root.string(),customAssets,second,error),"cook respects ordinary project custom asset directory");customAssets.Scan(root.string(),(root/"Content").string());Check(customAssets.Find(custom.meshId)&&customAssets.Find(custom.textureId)&&customAssets.Find(custom.collisionId),"custom asset directory registers all normal products");auto customFork=ForkTerrain(custom);Check(fs::path(customFork.productDirectory).parent_path()==fs::path("Content/Terrain"),"fork preserves owning asset-directory convention");custom.productDirectory="Assets/not-discoverable";Write(customPath,SerializeTerrain(custom));Check(!CookTerrain(custom,customPath.string(),root.string(),customAssets,second,error),"cook rejects output outside normal configured asset discovery");
