 auto large=CreateTerrain(65,65,64,64);CollisionAsset largeAsset;Check(CookCollision(BuildTerrainMesh(large),{},largeAsset,error),"representative large mesh cook");PhysicsWorld motorGeometry;motorGeometry.Init();motorGeometry.CreateShape(Shape::Cooked(std::make_shared<CollisionAsset>(largeAsset),"large"),{{0,0,0},glm::quat(1,0,0,0)},false,0,.5f,0);ResetCollisionGeometryStats();auto sweep=motorGeometry.SweepCapsuleMotion(.3f,.6f,{.17f,1,.31f},glm::quat(1,0,0,0),{0,-.3f,0});auto geometryWork=GetCollisionGeometryStats();Check(sweep.hit&&std::abs(sweep.distance-.1f)<2e-4,"motor sampled sweep retains analytic overlap boundary");Check(geometryWork.nodes>0&&geometryWork.triangles<2000,"motor sweep uses BVH bounded triangles rather than full mesh per sample");std::cout<<"MOTOR_BVH nodes "<<geometryWork.nodes<<" triangles "<<geometryWork.triangles<<" / mesh 8192\n";
 for(unsigned size:{65u,129u}){auto start=std::chrono::steady_clock::now();auto stress=CreateTerrain(size,size,float(size-1),float(size-1));TerrainDraft work;work.source=stress;b.kind=TerrainBrushKind::Raise;b.radius=5;work.Begin({-10,0,0},b,error);work.Continue({10,0,0},error);work.End();auto m=BuildTerrainMesh(work.source);auto ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();std::cout<<"PERF "<<size<<" grid stroke+normals "<<ms<<" ms / "<<m.vertices.size()<<" vertices\n";}
